"use client";

import * as React from "react";
import { DayButton, DayPicker } from "react-day-picker";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { buttonVariants } from "./button";
import { primaryFace, focusRing } from "./_shared";

/** Props for the Calendar: every react-day-picker prop passes through. */
export type CalendarProps = React.ComponentProps<typeof DayPicker>;

const navButton = cn(
  buttonVariants({ variant: "ghost", size: "icon-sm" }),
  "aria-disabled:pointer-events-none aria-disabled:opacity-50",
);

const chevronIcons = {
  left: "mingcute:left-line",
  right: "mingcute:right-line",
  up: "mingcute:up-line",
  down: "mingcute:down-line",
} as const;

/** The month arrows and dropdown chevron, drawn in MingCute. */
function CalendarChevron({
  orientation = "left",
  className,
}: {
  orientation?: keyof typeof chevronIcons;
  className?: string;
}) {
  return <Icon icon={chevronIcons[orientation]} aria-hidden="true" className={cn("size-4", className)} />;
}

/**
 * One day of the grid. A chosen day, and each end of a chosen range, wears
 * the solid teal fill of the primary Button; the days between sit in a light
 * grey band. Today reads in semibold teal text until it is chosen.
 */
function CalendarDayButton({
  className,
  modifiers,
  ...props
}: React.ComponentProps<typeof DayButton>) {
  const filled = modifiers.selected && !modifiers.range_middle;

  return (
    <DayButton
      modifiers={modifiers}
      data-slot="calendar-day"
      className={cn(
        className,
        modifiers.outside && "text-muted-foreground",
        modifiers.today && !modifiers.selected && "font-semibold text-(--primary-text)",
        modifiers.range_middle && "rounded-none bg-transparent hover:bg-transparent",
        filled && cn(primaryFace, "font-medium hover:bg-primary/88"),
        modifiers.disabled && "opacity-40",
      )}
      {...props}
    />
  );
}

/**
 * Paddock Calendar: a month of 2.25rem days with small rounded corners. The
 * month name sits in semibold between two ghost arrows; a chosen day fills
 * with solid teal, and a range runs as a grey band between two teal ends.
 */
function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  components,
  ...props
}: CalendarProps) {
  return (
    <DayPicker
      data-slot="calendar"
      showOutsideDays={showOutsideDays}
      className={cn("p-3", className)}
      classNames={{
        months: "relative flex flex-col gap-4 sm:flex-row",
        month: "flex flex-col gap-3",
        month_caption: "flex h-8 items-center justify-center",
        caption_label:
          "inline-flex items-center gap-1 text-sm font-semibold text-foreground [&_svg]:size-3.5 [&_svg]:text-muted-foreground",
        dropdowns: "flex items-center gap-2",
        dropdown_root:
          "relative inline-flex items-center rounded-sm px-1.5 hover:bg-accent has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring",
        dropdown: "absolute inset-0 cursor-pointer opacity-0",
        nav: "absolute inset-x-0 top-0 flex h-8 items-center justify-between",
        button_previous: navButton,
        button_next: navButton,
        month_grid: "w-full border-collapse",
        weekdays: "flex",
        weekday: "w-9 text-center text-xs font-medium text-muted-foreground",
        week: "mt-1 flex w-full",
        day: "relative size-9 p-0 text-center",
        day_button: cn(
          "inline-flex size-9 items-center justify-center rounded-md text-sm tabular-nums text-foreground",
          "transition-colors duration-fast ease-out hover:bg-accent",
          focusRing,
          "disabled:pointer-events-none",
        ),
        range_start: "rounded-s-full bg-muted",
        range_middle: "bg-muted",
        range_end: "rounded-e-full bg-muted",
        outside: "text-muted-foreground",
        disabled: "opacity-40",
        hidden: "invisible",
        week_number: "w-9 text-xs text-muted-foreground",
        footer: "pt-3 text-[0.8125rem] text-muted-foreground",
        ...classNames,
      }}
      components={{
        Chevron: CalendarChevron,
        DayButton: CalendarDayButton,
        ...components,
      }}
      {...props}
    />
  );
}
Calendar.displayName = "Calendar";

export { Calendar };
